import { describe, expect, it } from "vitest";
import { bindingsOf, distinctBindings } from "./bindings.ts";
import { generatorOf, generatedMark, type GeneratedFact } from "./exemptions/generated-file.ts";
import { openEngine } from "./session.ts";

const engine = openEngine({ collectTiming: false });
const MODULE = "ts://@example/app/gen.ts#";

/** The binding records one generated file publishes, read as the run reads it. */
function recordsOf(text: string): readonly string[] {
  const file = engine.parseSourceFile("/project/gen.ts", text);
  const mark = generatedMark(text);
  const generator = generatorOf(file);
  if (mark === undefined) {
    throw new Error("the text is not generated");
  }
  const fact: GeneratedFact = generator === undefined ? mark : { ...mark, generator };
  return distinctBindings(
    bindingsOf(
      new Map([["gen.ts", file]]),
      new Map([["gen.ts", fact]]),
      new Map([["gen.ts", MODULE]]),
      new Map(),
    ).records,
  ).map(
    (one) =>
      `${one.role} ${one.symbol.slice(MODULE.length) || ":file"} ${one.schema ?? one.scope ?? ""} ${one.schema_file}`,
  );
}

const ES_HEADER =
  '// @generated by protoc-gen-es v2.16.0 with parameter "target=ts"\n// @generated from file v1/a.proto (package v1, syntax proto3)\n\n';

const V1_HEADER =
  '// @generated by protoc-gen-es v1.10.0 with parameter "target=ts"\n// @generated from file v1/a.proto (package v1, syntax proto3)\n\n';

const V1_MESSAGES = `${V1_HEADER}export enum Mode {\n  UNSPECIFIED = 0,\n  FAST = 1,\n}\nproto3.util.setEnumType(Mode, "v1.Mode", [\n  { no: 0, name: "MODE_UNSPECIFIED" },\n  { no: 1, name: "MODE_FAST" },\n]);\n\nexport class Ping extends Message<Ping> {\n  textValue = "";\n  clone$ = 0;\n  kind: { value: string; case: "someName" } | { case: undefined; value?: undefined } = { case: undefined };\n  static readonly typeName = "v1.Ping";\n  static readonly fields: FieldList = proto3.util.newFieldList(() => [\n    { no: 1, name: "text_value", kind: "scalar", T: 9 },\n    { no: 2, name: "clone", kind: "scalar", T: 5 },\n    { no: 3, name: "some_name", kind: "scalar", T: 9, oneof: "kind" },\n  ]);\n}\n`;

const TS_PROTO_SCHEMA = `// Code generated by protoc-gen-ts_proto. DO NOT EDIT.\n// versions:\n//   protoc-gen-ts_proto  v2.15.0\n// source: v1/a.proto\n\nimport type { FileDescriptorProto } from "ts-proto-descriptors";\n\nexport const protobufPackage = "v1";\n\nexport enum Mode {\n  MODE_FAST = 0,\n  UNRECOGNIZED = -1,\n}\n\nexport interface Ping {\n  text: string;\n  result?: { $case: "ok"; ok: string } | undefined;\n}\n\nexport const Ping: MessageFns<Ping> = {\n  decode(input: BinaryReader): Ping {\n    const message = createBasePing();\n    while (reader.pos < end) {\n      const tag = reader.uint32();\n      switch (tag >>> 3) {\n        case 1: {\n          message.text = reader.string();\n          continue;\n        }\n        case 2: {\n          message.result = { $case: "ok", ok: reader.string() };\n          continue;\n        }\n      }\n    }\n    return message;\n  },\n};\n\nexport const protoMetadata: ProtoMetadata = {\n  fileDescriptor: {\n    "package": "v1",\n    "messageType": [{\n      "name": "Ping",\n      "field": [{ "name": "text", "number": 1 }, { "name": "ok", "number": 2 }],\n      "nestedType": [{ "name": "LabelsEntry", "field": [], "options": { "mapEntry": true } }],\n    }],\n    "enumType": [{ "name": "Mode", "value": [{ "name": "MODE_FAST", "number": 0 }] }],\n  },\n  references: { ".v1.Ping": Ping, ".v1.Mode": Mode },\n};\n`;

const TS_PROTO_HEADER =
  '// Code generated by protoc-gen-ts_proto. DO NOT EDIT.\n// versions:\n//   protoc-gen-ts_proto  v2.15.0\n// source: v1/a.proto\n\nexport const protobufPackage = "v1";\n\n';

describe("the binding identities of a protoc-gen-es v2 file", () => {
  it("binds messages, fields after a bracketed option list, schemas through their type argument, and a service with its RPCs", () => {
    expect(
      recordsOf(
        `${ES_HEADER}/**\n * @generated from message v1.Ping\n */\nexport type Ping = Message<"v1.Ping"> & {\n  /**\n   * @generated from field: string text = 2 [json_name = "words"];\n   */\n  text: string;\n  helper?: number;\n};\n\nexport const PingSchema: GenMessage<Ping> = messageDesc(file, 0);\n\nexport const file: GenFile = fileDesc("");\n\n/**\n * @generated from service v1.Pinger\n */\nexport const Pinger: GenService<{\n  /**\n   * @generated from rpc v1.Pinger.Ping\n   */\n  ping: { methodKind: "unary" },\n}> = serviceDesc(file, 0);\n`,
      ),
    ).toEqual([
      "consumer Ping proto://v1#Ping v1/a.proto",
      "consumer PingSchema proto://v1#Ping v1/a.proto",
      "consumer Ping.text proto://v1#Ping.text v1/a.proto",
      "consumer Pinger proto://v1#Pinger v1/a.proto",
      "consumer Pinger.ping proto://v1#Pinger.Ping v1/a.proto",
    ]);
  });

  it("binds a oneof constituent in the case-constituent form under its tag's proto name, and an enum with its values", () => {
    expect(
      recordsOf(
        `${ES_HEADER}/**\n * @generated from message v1.Policy\n */\nexport type Policy = Message<"v1.Policy"> & {\n  /**\n   * @generated from oneof v1.Policy.kind\n   */\n  kind: {\n    /**\n     * @generated from field: int32 keep_last = 1;\n     */\n    value: number;\n    case: "keepLast";\n  } | { case: undefined; value?: undefined };\n};\n\n/**\n * @generated from enum v1.Mode\n */\nexport enum Mode {\n  /**\n   * @generated from enum value: MODE_FAST = 0;\n   */\n  FAST = 0,\n}\n`,
      ),
    ).toEqual([
      "consumer Mode proto://v1#Mode v1/a.proto",
      "consumer Mode.FAST proto://v1#Mode.MODE_FAST v1/a.proto",
      "consumer Policy proto://v1#Policy v1/a.proto",
      "consumer Policy.kind.'keepLast':case proto://v1#Policy.keep_last v1/a.proto",
    ]);
  });

  it("ends the run where a oneof constituent carries no field tag", () => {
    expect(() =>
      recordsOf(
        `${ES_HEADER}/**\n * @generated from message v1.Policy\n */\nexport type Policy = Message<"v1.Policy"> & {\n  /**\n   * @generated from oneof v1.Policy.kind\n   */\n  kind: { value: number; case: "keepLast" } | { case: undefined; value?: undefined };\n};\n`,
      ),
    ).toThrow(
      /^setup failure: binding-undecodable: gen\.ts: the constituent Policy\.kind\.'keepLast':case carries no field tag/u,
    );
  });
});

describe("the decoding of a protoc-gen-es v2 file", () => {
  it("ends the run where a field tag names no field, the row holding the version", () => {
    expect(() =>
      recordsOf(
        `${ES_HEADER}/**\n * @generated from message v1.Ping\n */\nexport type Ping = Message<"v1.Ping"> & {\n  /**\n   * @generated from field: string text;\n   */\n  text: string;\n};\n`,
      ),
    ).toThrow(
      /^setup failure: binding-undecodable: gen\.ts: the tag of Ping\.text names no field or value, so it does not decode as generator row protoc-gen-es-2 states/u,
    );
  });

  it("ends the run where a schema constant's type argument names no tagged type", () => {
    expect(() =>
      recordsOf(`${ES_HEADER}export const PingSchema: GenMessage<Ping> = messageDesc(file, 0);\n`),
    ).toThrow(
      /^setup failure: binding-undecodable: gen\.ts: PingSchema names no type the file tags/u,
    );
  });
});

describe("the binding identities of a protoc-gen-es v1 or protoc-gen-connect-es v1 file", () => {
  it("binds a class by its typeName, each field by its fields entry, a oneof member by its case, and an enum by setEnumType", () => {
    expect(recordsOf(V1_MESSAGES)).toEqual([
      "consumer Mode proto://v1#Mode v1/a.proto",
      "consumer Mode.FAST proto://v1#Mode.MODE_FAST v1/a.proto",
      "consumer Mode.UNSPECIFIED proto://v1#Mode.MODE_UNSPECIFIED v1/a.proto",
      "consumer Ping proto://v1#Ping v1/a.proto",
      "consumer Ping.clone$ proto://v1#Ping.clone v1/a.proto",
      "consumer Ping.kind.'someName':case proto://v1#Ping.some_name v1/a.proto",
      "consumer Ping.textValue proto://v1#Ping.text_value v1/a.proto",
    ]);
  });

  it("binds a service literal by its typeName and each method member by its name", () => {
    expect(
      recordsOf(
        `// @generated by protoc-gen-connect-es v1.6.1 with parameter "target=ts"\n// @generated from file v1/a.proto (package v1, syntax proto3)\n\nexport const Pinger = {\n  typeName: "v1.Pinger",\n  methods: {\n    ping: { name: "Ping", I: Ping, O: Ping, kind: MethodKind.Unary },\n  },\n} as const;\n`,
      ),
    ).toEqual([
      "consumer Pinger proto://v1#Pinger v1/a.proto",
      "consumer Pinger.methods.ping proto://v1#Pinger.Ping v1/a.proto",
    ]);
  });

  it("binds a file its row, which holds no version interval, cannot decode as one fallback of scope all", () => {
    expect(recordsOf(V1_MESSAGES.replace('name: "clone"', 'name: "copy"'))).toEqual([
      "fallback :file all v1/a.proto",
    ]);
  });
});

describe("the binding identities of a ts-proto file", () => {
  it("binds each RPC of a service name's interface by the proto name its client class method passes the transport, and publishes the file as a fallback of scope types", () => {
    const client = [
      "export interface Pinger {",
      "  ping(request: Ping): Promise<Ping>;",
      "  getLast(request: Ping): Promise<Ping>;",
      "  batched(request: Ping): Promise<Ping>;",
      "}",
      'export const PingerServiceName = "v1.Pinger";',
      "export class PingerClientImpl implements Pinger {",
      "  private readonly rpc: Rpc;",
      "  private readonly service: string;",
      "  constructor(rpc: Rpc) {",
      "    this.service = PingerServiceName;",
      "    this.rpc = rpc;",
      "  }",
      "  ping(request: Ping): Promise<Ping> {",
      '    return this.rpc.request(this.service, "Ping", Ping.encode(request).finish());',
      "  }",
      "  getLast(request: Ping): Promise<Ping> {",
      '    return this.rpc.request(ctx, "v1.Pinger", "GetLast", Ping.encode(request).finish());',
      "  }",
      "  batched(request: Ping): Promise<Ping> {",
      "    return this.getLast(request);",
      "  }",
      "}",
      "",
    ].join("\n");
    expect(
      recordsOf(`${TS_PROTO_HEADER}export interface Ping {\n  text: string;\n}\n\n${client}`),
    ).toEqual([
      "fallback :file types v1/a.proto",
      "consumer Pinger.getLast proto://v1#Pinger.GetLast v1/a.proto",
      "consumer Pinger.ping proto://v1#Pinger.Ping v1/a.proto",
    ]);
  });

  it("binds a definition's members by their path, and the definition and its client as the service", () => {
    expect(
      recordsOf(
        `${TS_PROTO_HEADER}export const PingerService = {\n  ping: { path: "/v1.Pinger/Ping", requestStream: false },\n} as const;\n\nexport interface PingerClient {\n  ping(request: unknown): Promise<unknown>;\n}\n`,
      ),
    ).toEqual([
      "fallback :file types v1/a.proto",
      "consumer PingerClient proto://v1#Pinger v1/a.proto",
      "consumer PingerService proto://v1#Pinger v1/a.proto",
      "consumer PingerClient.ping proto://v1#Pinger.Ping v1/a.proto",
      "consumer PingerService.ping proto://v1#Pinger.Ping v1/a.proto",
    ]);
  });

  it("binds an outputSchema file's descriptor through its references map, its decode cases and its enum numbers", () => {
    expect(recordsOf(TS_PROTO_SCHEMA)).toEqual([
      "consumer Mode proto://v1#Mode v1/a.proto",
      "consumer Mode.MODE_FAST proto://v1#Mode.MODE_FAST v1/a.proto",
      "consumer Ping proto://v1#Ping v1/a.proto",
      "consumer Ping.result.'ok':case proto://v1#Ping.ok v1/a.proto",
      "consumer Ping.text proto://v1#Ping.text v1/a.proto",
    ]);
  });

  it("ends the run where an outputSchema file's decode assigns nothing for a field the descriptor numbers", () => {
    expect(() => recordsOf(TS_PROTO_SCHEMA.replace("case 1: {", "case 7: {"))).toThrow(
      /^setup failure: binding-undecodable: gen\.ts: the decode of Ping assigns no property Ping declares for field 1, so it does not decode as generator row ts-proto-2-output-schema states/u,
    );
  });

  it("publishes outputSchema output whose descriptor, message references or decoders are left out as ts-proto output of another option set", () => {
    const outputs = [
      TS_PROTO_SCHEMA.replace(
        /decode\(input[\s\S]*?return message;\n {2}\},/u,
        'decode(): Ping {\n    throw new Error("decode not generated for Ping");\n  },',
      ),
      TS_PROTO_SCHEMA.replace('".v1.Ping": Ping, ', ""),
      TS_PROTO_SCHEMA.replace(/ {2}fileDescriptor: \{[\s\S]*?\n {2}\},\n/u, ""),
      TS_PROTO_SCHEMA.replace("switch (tag >>> 3) {", "switch (typeof input) {"),
    ];
    for (const output of outputs) {
      expect(output).not.toBe(TS_PROTO_SCHEMA);
      expect(recordsOf(output)).toEqual(["fallback :file all v1/a.proto"]);
    }
  });

  it("publishes a file that writes no service path as one fallback of scope all, and binds nothing in it", () => {
    expect(recordsOf(`${TS_PROTO_HEADER}export interface Ping {\n  text: string;\n}\n`)).toEqual([
      "fallback :file all v1/a.proto",
    ]);
  });
});
